def abstract(id,title,sents,asked=('Background','Purpose','Methodology','Results'),pool='original',extra=None):
 roles=['Background','Purpose','Methodology','Results','Conclusion / implications'];parts=[]
 for n,role in enumerate(asked):
  idx=roles.index(role);parts.append(dict(id=f'p{n+1}',name=role,accepted=[sents[idx]],explanation=f'{role}: '+['establishes the context or problem rather than the study action.','states what the investigation aimed to establish.','specifies participants, material or the procedure used.','reports the observed outcome rather than an intention.','interprets the findings or states their wider use.'][idx]))
 q=dict(id=id,subject='wp',topic='abstracts',title=title,source='Original practice' if pool=='original' else 'Exclusive mock',difficulty='Exam',pool=pool,type='abstract-parts',partLabel='Q5A',marks=4,suggestedMinutes=12,prompt='Write out the exact sentence(s) for each of the four named parts. Do not enter only a letter or paraphrase.',abstract=' '.join(sents),parts=parts)
 if extra:q.update(extra)
 return q
abstract_specs=[
('Reminder clarity',['Missed appointments can disrupt small clinic schedules.','This study aimed to determine whether patients understood a revised reminder message.','Researchers asked 60 consenting patients to explain the message in their own words.','Fifty-two patients correctly identified both the appointment time and the rescheduling number.','The findings suggest that the revised wording is understandable to most participants, although a larger sample is needed.']),
('Coding feedback',['Beginning programmers often receive feedback only after completing an entire assignment.','The purpose of this study was to compare brief weekly feedback with feedback given at the end of a unit.','Two introductory classes completed the same tasks, and their revisions were assessed using a common rubric.','The weekly-feedback class corrected more of the previously identified errors in its final submissions.','Regular feedback may support revision, but the class-based design does not isolate every influence.']),
('Refill use',['Campus refill facilities can remain underused when their locations are unclear.','This investigation examined whether additional signs improved awareness of refill points.','A survey of 80 students was conducted before and after signs were installed at four entrances.','The proportion able to identify a nearby refill point increased from 45% to 70%.','Visible signage appears useful for awareness, although the survey did not measure water consumption.']),
('Hybrid meetings',['Hybrid meetings require coordination between people in different locations.','This study sought to identify obstacles to participation among remote team members.','Researchers interviewed 18 employees and reviewed notes from six team meetings.','Participants most frequently reported difficulty hearing discussion in the meeting room.','Improved audio arrangements should be evaluated before assuming that attendance alone ensures participation.']),
('Reading choices',['Children differ in their interests and prior reading experiences.','The aim was to examine how a choice of books influenced participation in a reading club.','Observers recorded voluntary contributions during eight sessions with 24 children.','More children contributed during sessions in which several age-appropriate books were available.','Offering choice may encourage participation, but the small observational study cannot establish causation.']),
('Repair records',['Equipment replacement decisions are often made without consistent fault records.','This study investigated whether a shared repair log could support purchasing decisions.','Technicians recorded faults and repair costs for 50 devices over one term.','Repeated connector faults accounted for 18 of the 50 recorded cases.','The log can identify recurring problems, although purchasing changes require further cost analysis.']),
('Shaded routes',['Pedestrians may avoid exposed campus routes during warm afternoons.','The study aimed to compare reported comfort on shaded and exposed walking routes.','Forty volunteers rated two routes immediately after walking them on the same afternoon.','The shaded route received a higher median comfort rating than the exposed route.','Shade may improve perceived comfort under the observed conditions, but seasonal comparisons remain necessary.']),
('Accessible documents',['Image-only reading files can prevent efficient use of assistive software.','The purpose of the investigation was to assess the accessibility of first-year course readings.','Two trained reviewers tested 100 files against a shared accessibility checklist.','Twenty-eight files lacked searchable text and twelve lacked meaningful heading structure.','Routine document checks may help identify access barriers before readings are distributed.'])]
for i,(t,s) in enumerate(abstract_specs):original.append(abstract(f'wp-abstract-{i+1:02}',t,s,('Purpose','Methodology','Results','Conclusion / implications') if i%2 else ('Background','Purpose','Methodology','Results')))
def grammar(id,title,o,c,errors,pool='original'):
 return dict(id=id,subject='wp',topic='grammar',title=title,source='Original practice' if pool=='original' else 'Exclusive mock',difficulty='Exam',pool=pool,type='grammar-rewrite',partLabel='Q5B',marks=6,suggestedMinutes=18,prompt='Rewrite the entire paragraph, correcting every error. Highlight each correction using the selection button or ==correction==. Preserve the meaning.',original=o,corrected=c,errors=[dict(id=f'e{i+1}',error=e,correction=c,rule=r) for i,(e,c,r) in enumerate(errors)],explanation='Read the complete rewrite first. Scan agreement, tense, articles, prepositions, word form and punctuation. The automatic count checks phrases, not the quality of the whole paragraph. Compare the full diff and self-adjust if your valid rewrite uses another construction. Highlights are checked separately; mark every change.')
grammar_specs=[
('Library survey','The students was asked to complete a survey yesterday. Each response were checked careful by a librarian. The team discussed about the results and found that many student preferred a quiet room. A report was send to the manager, she promised to improve the signs.','The students were asked to complete a survey yesterday. Each response was checked carefully by a librarian. The team discussed the results and found that many students preferred a quiet room. A report was sent to the manager, who promised to improve the signs.', [('students was','students were','A plural subject takes were.'),('response were','response was','Each response is singular.'),('checked careful','checked carefully','An adverb modifies checked.'),('discussed about the results','discussed the results','Discuss takes a direct object.'),('many student','many students','Many requires a plural count noun.'),('was send','was sent','The passive needs a past participle.'),('manager, she','manager, who','A relative clause repairs the comma splice.')]),
('Office equipment','Our office have received an new printer. It arrive on Monday, but two cable were missing. The supplier asked us to send the informations by email. We has attached photographs the support team will reply tomorrow.','Our office has received a new printer. It arrived on Monday, but two cables were missing. The supplier asked us to send the information by email. We have attached photographs, and the support team will reply tomorrow.', [('office have','office has','Office is singular.'),('an new printer','a new printer','New begins with a consonant sound.'),('It arrive on Monday','It arrived on Monday','A completed past event needs the past tense.'),('two cable','two cables','Two requires a plural noun.'),('the informations','the information','Information is uncountable.'),('We has','We have','We takes have.'),('photographs the support','photographs, and the support','The original is a run-on: join the complete clauses with a comma and conjunction.')]),
('Garden volunteers','The gardening club organise a visit last Friday. A volunteer explain the plan to we. Before the work began. There was several damaged pots near a entrance. Everyone agreed that the path needed urgent repair, the club wrote to the manager immediate.','The gardening club organised a visit last Friday. A volunteer explained the plan to us before the work began. There were several damaged pots near an entrance. Everyone agreed that the path needed urgent repair, so the club wrote to the manager immediately.', [('club organise a visit','club organised a visit','Last Friday establishes past time.'),('volunteer explain','volunteer explained','Keep the past tense consistent.'),('to we','to us','Use the object pronoun after a preposition.'),('we. Before the work began.','us before the work began.','Before the work began is a dependent-clause fragment; join it to the preceding main clause.'),('There was several','There were several','The plural noun pots requires were.'),('a entrance','an entrance','Entrance begins with a vowel sound.'),('repair, the club','repair, so the club','A conjunction connects the two complete clauses.'),('manager immediate','manager immediately','An adverb modifies wrote.')]),
('Training announcement','Every employee are invited to a workshop on Friday. The session will begins at ten, and participants should brings a notebook. The trainer will explain how to write clear emails. Please register untill Wednesday and send your name to the coordinator, he will confirm you place.','Every employee is invited to a workshop on Friday. The session will begin at ten, and participants should bring a notebook. The trainer will explain how to write clear emails. Please register by Wednesday and send your name to the coordinator, who will confirm your place.', [('employee are','employee is','Every employee is singular.'),('will begins','will begin','Will is followed by a base verb.'),('should brings','should bring','Should takes a base verb.'),('register untill Wednesday','register by Wednesday','By sets a deadline; until describes continuation. The original also misspells until.'),('coordinator, he','coordinator, who','A relative clause avoids the comma splice.'),('you place','your place','Use the possessive determiner your.')]),
('Health desk','The clinic open a help desk last week. Patients was given an useful guide about appointments. The guide contain details of each services. A nurse spoke polite to visitors and answered there questions. The desk was busy, it remained open for an extra hour.','The clinic opened a help desk last week. Patients were given a useful guide about appointments. The guide contains details of each service. A nurse spoke politely to visitors and answered their questions. The desk was busy, so it remained open for an extra hour.', [('clinic open','clinic opened','Last week requires a past-tense event.'),('Patients was','Patients were','Patients is plural.'),('an useful guide','a useful guide','Useful begins with a consonant /y/ sound.'),('guide contain','guide contains','A current description with singular guide takes contains.'),('each services','each service','Each takes a singular count noun.'),('spoke polite','spoke politely','Use an adverb with spoke.'),('there questions','their questions','Their indicates possession.'),('busy, it remained','busy, so it remained','Use a conjunction between independent clauses.')]),
('Project review','Yesterday, our team meet to review the project. Neither of the two proposals were ready. The manager asked for a explanation and advised us to revise the plan careful. We agreed to complete the changes in Monday. The meeting ended late, everyone returned to their desk.','Yesterday, our team met to review the project. Neither of the two proposals was ready. The manager asked for an explanation and advised us to revise the plan carefully. We agreed to complete the changes on Monday. The meeting ended late, and everyone returned to their desk.', [('team meet','team met','Yesterday requires the past tense.'),('Neither of the two proposals were ready','Neither of the two proposals was ready','Neither is the singular head; proposals is inside the of-phrase.'),('a explanation','an explanation','Explanation begins with a vowel sound.'),('plan careful','plan carefully','An adverb modifies revise.'),('changes in Monday','changes on Monday','Use on with a named day.'),('late, everyone','late, and everyone','Repair the comma splice. Singular their is acceptable with everyone.')]),
('Travel notice','There is many changes to the shuttle timetable. The first bus leave at eight every morning. Yesterday, several passenger waits at the old stop. The driver explained the new route to they. Please check the notice careful before you travel, the map is attached below.','There are many changes to the shuttle timetable. The first bus leaves at eight every morning. Yesterday, several passengers waited at the old stop. The driver explained the new route to them. Please check the notice carefully before you travel; the map is attached below.', [('There is many','There are many','Changes is plural.'),('bus leave','bus leaves','The singular bus takes leaves in a routine.'),('several passenger','several passengers','Several requires a plural noun.'),('passenger waits','passengers waited','Yesterday requires waited and a plural subject.'),('to they','to them','A preposition takes an object pronoun.'),('notice careful','notice carefully','Use an adverb to modify check.'),('travel, the map','travel; the map','A semicolon can join complete related clauses.')]),
('Reading session','Each of the children were at the centre yesterday. The volunteer give each child an book. They read quiet for ten minute before discussing the story. One child asked a question, the volunteer answer it clearly. The children enjoyed themself.','Each of the children was at the centre yesterday. The volunteer gave each child a book. They read quietly for ten minutes before discussing the story. One child asked a question, and the volunteer answered it clearly. The children enjoyed themselves.', [('Each of the children were','Each of the children was','Each is the singular head of the subject.'),('volunteer give','volunteer gave','Use past tense in a past narrative.'),('an book','a book','Book begins with a consonant sound.'),('read quiet','read quietly','Use the adverb quietly.'),('ten minute','ten minutes','Ten requires a plural noun.'),('question, the volunteer','question, and the volunteer','Repair the comma splice.'),('volunteer answer it','volunteer answered it','Keep the past tense.'),('enjoyed themself','enjoyed themselves','The plural subject children needs themselves.')]),
('Research poster','The researcher have prepared a poster. It describes an experiment that begin last month. The results shows a difference between two group. The team is confident about the method, they still acknowledge its limited. Each participant gave their consent voluntary.','The researcher has prepared a poster. It describes an experiment that began last month. The results show a difference between two groups. The team is confident about the method, but they still acknowledge its limitations. Each participant gave their consent voluntarily.', [('researcher have','researcher has','Researcher is singular.'),('that begin last month','that began last month','The experiment began in the past.'),('results shows','results show','Results is plural.'),('two group','two groups','Two requires a plural noun.'),('method, they','method, but they','A conjunction repairs the comma splice.'),('its limited','its limitations','A noun is needed after the possessive determiner.'),('consent voluntary','consent voluntarily','An adverb modifies gave; singular their is correct.')]),
('Course feedback','These feedback are important to the tutor. She ask students to complete a form yesterday. The form had less questions than the previous version. Everyone were allowed to skip an sensitive item. Students responded honest, the tutor thanked them for there time.','This feedback is important to the tutor. She asked students to complete a form yesterday. The form had fewer questions than the previous version. Everyone was allowed to skip a sensitive item. Students responded honestly, and the tutor thanked them for their time.', [('These feedback are','This feedback is','Feedback is uncountable and takes a singular determiner and verb.'),('She ask students','She asked students','Yesterday requires past tense.'),('less questions','fewer questions','Use fewer with plural count nouns.'),('Everyone were','Everyone was','Everyone is singular.'),('an sensitive item','a sensitive item','Sensitive begins with a consonant sound.'),('responded honest','responded honestly','Use an adverb with responded.'),('honest, the tutor','honestly, and the tutor','Repair the comma splice while correcting the adverb.'),('there time','their time','Their is the possessive form.')])]
for i,(t,o,c,e) in enumerate(grammar_specs):original.append(grammar(f'wp-grammar-{i+1:02}',t,o,c,e))
